<?php if($recent): ?><section class="history"><small>RECENT SEARCHES</small><h2>最近の検索</h2><div class="cards"><?php foreach($recent as $recentSearch): ?><?php if($recentSearch['search_type'] === 'flight'): ?><button type="button" class="recent-search-card" data-search-type="flight" data-origin="<?= $h($recentSearch['origin']) ?>" data-destination="<?= $h($recentSearch['destination']) ?>" data-departure-date="<?= $h($recentSearch['departure_date']) ?>" data-return-date="<?= $h($recentSearch['return_date'] ?? '') ?>" data-travelers="<?= $h($recentSearch['travelers']) ?>"><small class="recent-search-type">✈ 航空券</small><b><?= $h($recentSearch['origin']) ?> → <?= $h($recentSearch['destination']) ?></b><span><?= $h($recentSearch['departure_date']) ?><?= !empty($recentSearch['return_date'])?' 〜 '.$h($recentSearch['return_date']):'' ?>・<?= $h($recentSearch['travelers']) ?>名</span></button><?php else: ?><button type="button" class="recent-search-card" data-search-type="hotel" data-destination="<?= $h($recentSearch['destination']) ?>" data-check-in="<?= $h($recentSearch['check_in']) ?>" data-check-out="<?= $h($recentSearch['check_out']) ?>" data-adults="<?= $h($recentSearch['adults']) ?>" data-children="<?= $h($recentSearch['children']) ?>"><small class="recent-search-type">▣ ホテル</small><b><?= $h($recentSearch['destination']) ?></b><span><?= $h($recentSearch['check_in']) ?> 〜 <?= $h($recentSearch['check_out']) ?>・大人<?= $h($recentSearch['adults']) ?>名・子供<?= $h($recentSearch['children']) ?>名</span></button><?php endif ?><?php endforeach ?></div></section><?php endif ?>
